// baseURL is the API base address with a ws:// or wss:// scheme; add authentication as your deployment requires.
const ws = new WebSocket(baseURL.replace(/\/$/, "") + "/Control/Watch", "xrpc.json");
ws.onopen = () => ws.send(JSON.stringify({ jsonrpc: "2.0", method: "Control.Watch", params: { /* WatchRequest */ }, id: 1 }));
ws.onmessage = (event) => {
  const frame = JSON.parse(event.data);
  if (frame.method === "xrpc.message") console.log(frame.params.data); // Event
};
